import fs from 'node:fs';
import assert from 'node:assert/strict';
import '../economy-audit/source-loader.mjs';
import {entry} from './question-bank-batch2b-round2-specs-20261104.mjs';
const c=await import('../../packages/clinical-content/src/index.ts');
const {QUESTION_SHIP_MANIFEST:manifest}=await import('../../packages/clinical-content/src/question-ship-manifest.ts');
const {projectManagerAcceptedQuestions}=await import('../../packages/clinical-content/src/question-ship-projection.ts');
const {EXACT_TEST_CHOICE_ORDER_RECORDS:orders}=await import('../../packages/game-domain/src/test-choice-orders.ts');
const views={legacy:c.QUESTION_FLAGS_PRE_REVISION_RELEASE,'flags-round3':c.QUESTION_NEW_N1_PRE_RELEASE,'batch2a-round3':c.QUESTION_BANK_BATCH2A_ROUND3_RELEASE,'n1-round2':c.QUESTION_BANK_PRE_BATCH2B_RELEASE,'n2-round2':c.QUESTION_NEW_N1_ROUND3_PRE_RELEASE};
const baseline=projectManagerAcceptedQuestions(c.QUESTION_CATALOG_RELEASE,views);
assert.deepEqual(c.SYNTHETIC_CLINICAL_RELEASE,baseline,'Round-two integration changed unaccepted live content/cards');
assert.equal(JSON.stringify(c.SYNTHETIC_CLINICAL_RELEASE),JSON.stringify(baseline),'Live property/array order changed');
assert.equal(c.withAcceptedQuestionBankBatch2bRound2Concepts(c.QUESTION_CATALOG_RELEASE),c.QUESTION_CATALOG_RELEASE);
const ids=new Set(c.QUESTION_BANK_BATCH2B_ROUND2_REVISIONS.map(r=>r.questionVariantId));
assert.equal(manifest.accepted.filter(a=>ids.has(a.questionVariantId)).length,0);
const identity=v=>JSON.stringify([v.caseId,v.nodeId,v.questionVariantId]);
const timingMap=new Map(c.ANSWER_CHOICE_TIMING_REGISTRY.map(t=>[identity(t),t]));
for(const t of entry.timings)assert.deepEqual(timingMap.get(identity(t)),t,'Old timing changed: '+identity(t));
const orderIdentity=v=>JSON.stringify([v.caseId,v.nodeId,v.questionVariantId,v.choiceId]);
const orderMap=new Map(orders.map(o=>[orderIdentity(o),o]));
for(const o of entry.orders)assert.deepEqual(orderMap.get(orderIdentity(o)),o,'Old order changed: '+orderIdentity(o));
const report={policy:'Same current manager-manifest and domain implementation; only this worker’s round-two wrapper/source registration is omitted from the baseline. This is a structural control, not a substitute for full Vitest runs.',passed:true,defaultReleaseExactlyEqualWithoutOwnWrapper:true,workerAddedAcceptances:0,newLiveVariants:0,newLiveConceptCards:0,retainedTimingRows:entry.timings.length,retainedExactOrders:entry.orders.length,liveCases:c.SYNTHETIC_CLINICAL_RELEASE.cases.length,liveNodes:c.SYNTHETIC_CLINICAL_RELEASE.cases.flatMap(c=>c.decisionNodes).length,liveConcepts:c.SYNTHETIC_CLINICAL_RELEASE.concepts.length};
fs.writeFileSync('tools/question-quality/question-bank-batch2b-round2-live-control-20261104.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report));
